SELECT "tradeid", "currenttradeid", "sk_customerid", "sk_accountid", "sk_securityid", "sk_companyid", "sk_dateid", "sk_timeid", "currentprice", "currentholding", "batchid" FROM (SELECT TRY_CAST((CAST(hh.HH_H_T_ID AS INT)) AS int) AS "tradeid", TRY_CAST((CAST(hh.HH_T_ID AS INT)) AS int) AS "currenttradeid", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "sk_customerid", TRY_CAST((CAST(t.T_CA_ID AS INT)) AS int) AS "sk_accountid", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "sk_securityid", TRY_CAST((CAST(NULL AS INTEGER)) AS int) AS "sk_companyid", TRY_CAST((CAST(strftime(t.T_DTS, '%Y%m%d') AS INTEGER)) AS int) AS "sk_dateid", TRY_CAST((CAST(strftime(t.T_DTS, '%Y%m%d') AS INTEGER)) AS int) AS "sk_timeid", TRY_CAST((CAST(t.T_TRADE_PRICE AS INT)) AS int) AS "currentprice", TRY_CAST((hh.HH_AFTER_QTY) AS decimal(6)) AS "currentholding", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS decimal(5)) AS "batchid" FROM HoldingHistory hh LEFT JOIN Trade t ON hh.HH_T_ID = t.T_ID)
